    "recipesV83.JJ-E05-153.ingredient.4": "ginger",
    "recipesV83.JJ-E05-153.ingredient.5": "galangal",
    "recipesV83.JJ-E05-153.ingredient.6": "lemongrass",
    "recipesV83.JJ-E05-153.ingredient.7": "red chilli pepper",
